<template>
  <view class="page-shell home-page">
    <view class="home-head"><view><text class="date-label">{{ dateText }}</text><text class="home-title">{{ greeting }}</text><text class="home-intro">先看看接下来要准备什么，再去联系你在乎的人。</text></view><view class="head-actions"><button aria-label="新建记录" @tap="openCreateMenu">＋</button><view class="avatar" @tap="goProfile"><image v-if="hasAvatar" :src="store.userInfo.avatar" mode="aspectFill" @error="onAvatarError" /><text v-else>{{ displayName.slice(0, 1) }}</text></view></view></view>

    <view v-if="loading" class="next-card loading-card"><view></view><view></view><view></view></view>
    <view v-else-if="loadError" class="next-card error-next"><text class="next-kicker">暂时无法同步</text><text class="next-title">重要日子没有丢失</text><text class="error-copy">请检查网络后重新加载。</text><button class="retry-button" @tap="loadHome">重新加载</button></view>
    <view v-else-if="nearestReminder" class="next-card" @tap="goReminder(nearestReminder)"><view class="next-kicker">下一件重要的事</view><text class="next-title">{{ nearestReminder.eventTitle }}</text><view class="event-meta"><view class="mini-avatar coral">{{ personName(nearestReminder).slice(0, 1) }}</view><text>关联 · {{ personName(nearestReminder) }}</text></view><view class="event-date"><view class="event-date-number"><text>时间</text><strong>{{ dayNumber(nearestReminder.eventDate) }}</strong><em>{{ monthLabel(nearestReminder.eventDate) }}</em></view><view class="event-date-copy"><text>倒计时</text><strong>{{ eventDays(nearestReminder) === 0 ? '今天' : `还有 ${eventDays(nearestReminder)} 天` }}</strong><text>准备总会来得及</text></view></view><view class="next-actions"><button @tap.stop="openAI('blessing', nearestReminder)">写祝福</button><button @tap.stop="openAI('gift', nearestReminder)">礼物建议</button></view></view>
    <view v-else class="next-card empty-next" @tap="addEvent"><view class="empty-date-mark">＋</view><view><text>添加一个重要日子</text><text>生日、纪念日或下一次见面</text></view><text>›</text></view>

    <view v-if="!loadError" class="insight-card"><view class="section-head"><text>本周记录概览</text><text @tap="goMemories">查看全部记录 →</text></view><text class="insight-copy">{{ insightCopy }}</text><view class="insight-stats"><view><strong>{{ weekEventCount }}</strong><text>事件</text></view><view><strong>{{ weekMemoryCount }}</strong><text>回忆</text></view><view><strong>{{ weekRecordCount }}</strong><text>新增记录</text></view></view></view>

    <view v-if="!loadError" class="week-section"><view class="section-head"><text>未来一周</text><text @tap="goCalendar">查看完整日历 →</text></view><view class="week-strip"><view v-for="day in weekDays" :key="day.key" :class="{ today: day.isToday, busy: day.count }" @tap="goCalendarDay(day.key)"><text>{{ day.weekday }}</text><text>{{ day.day }}</text><text class="day-dot"></text></view></view><view v-if="weekReminders.length" class="agenda-list"><view v-for="item in weekReminders" :key="reminderKey(item)" class="agenda-row" @tap="goReminder(item)"><view class="agenda-avatar">{{ personName(item).slice(0, 1) }}</view><view><text>{{ item.eventTitle }}</text><text>{{ personName(item) }}</text></view><view class="agenda-when"><text>{{ eventDays(item) === 0 ? '今天' : `${eventDays(item)}天后` }}</text><text>{{ shortDate(item.eventDate) }}</text></view></view></view><view v-else-if="!loading" class="quiet-empty">这一周没有需要准备的日子</view></view>

    <view v-if="!loadError" class="people-section"><view class="section-head"><text>最近在乎的人</text><text @tap="goRelationships">全部联系人 →</text></view><view v-if="focusPeople.length" class="people-list"><view v-for="(item,index) in focusPeople" :key="item.id" class="person-row" @tap="goDetail(item.id)"><view class="person-avatar" :class="`tone-${index % 4}`">{{ item.name.slice(0, 1) }}</view><view class="person-copy"><text>{{ item.name }}</text><text>{{ item.type }} · {{ item._count?.memories || 0 }} 条记录</text></view><view v-if="nextFor(item.id)" class="person-next"><text>{{ eventDays(nextFor(item.id)) === 0 ? '今天' : `${eventDays(nextFor(item.id))}天后` }}</text><text>{{ nextFor(item.id).eventTitle }}</text></view><text v-else class="row-arrow">›</text></view></view><view v-else-if="!loading" class="add-person-row" @tap="goCreateRelationship"><text>＋</text><view><text>添加第一个联系人</text><text>从一个重要的人开始</text></view><text>›</text></view></view>

    <BottomNav active="home" :reminder-count="todayReminders.length" />
  </view>
</template>

<script setup>
import { computed, ref } from 'vue';
import { onHide, onShow, onUnload } from '@dcloudio/uni-app';
import BottomNav from '@/components/BottomNav.vue';
import { store } from '@/store/index.js';
import { relationshipApi } from '@/api/relationship.js';
import { eventApi } from '@/api/event.js';
import { openContactCreationMenu } from '@/utils/contactCreation.js';
import { trackEvent } from '@/utils/analytics.js';

const relationships = ref([]); const todayReminders = ref([]); const upcomingReminders = ref([]); const loading = ref(true); const loadError = ref(false); const avatarLoadFailed = ref(false);
const displayName = computed(() => store.userInfo?.nickname || '你');
const hasAvatar = computed(() => Boolean(store.userInfo?.avatar) && !avatarLoadFailed.value);
const dateText = computed(() => { const date = new Date(); return `${date.getMonth() + 1}月${date.getDate()}日 · ${['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'][date.getDay()]}`; });
const greeting = computed(() => { const hour = new Date().getHours(); return `${hour < 11 ? '早上好' : hour < 18 ? '下午好' : '晚上好'}，${displayName.value}`; });
const reminderKey = (item) => `${item.sourceType || 'RELATIONSHIP'}:${item.eventId || item.sharedEventId}:${item.eventDate}`;
const eventDays = (item) => { if (item?.daysUntilEvent !== null && item?.daysUntilEvent !== undefined && Number.isFinite(Number(item.daysUntilEvent))) return Math.max(0, Number(item.daysUntilEvent)); const target = new Date(item?.eventDate); const today = new Date(); target.setHours(0, 0, 0, 0); today.setHours(0, 0, 0, 0); return Number.isNaN(target.getTime()) ? 0 : Math.max(0, Math.round((target - today) / 86400000)); };
const allReminders = computed(() => { const map = new Map(); for (const item of [...todayReminders.value, ...upcomingReminders.value]) if (!map.has(reminderKey(item))) map.set(reminderKey(item), item); return [...map.values()].sort((a, b) => eventDays(a) - eventDays(b)); });
const nearestReminder = computed(() => allReminders.value[0] || null); const weekReminders = computed(() => allReminders.value.filter((item) => eventDays(item) <= 7).slice(0, 4));
const weekDays = computed(() => Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() + index); const key = toDateKey(date); return { key, day: date.getDate(), weekday: ['日', '一', '二', '三', '四', '五', '六'][date.getDay()], isToday: index === 0, count: allReminders.value.filter((item) => toDateKey(new Date(item.eventDate)) === key).length }; }));
const nextFor = (id) => allReminders.value.find((item) => item.relationshipId === id); const focusPeople = computed(() => [...relationships.value].sort((a, b) => { const left = nextFor(a.id); const right = nextFor(b.id); if (left && right) return eventDays(left) - eventDays(right); if (left) return -1; if (right) return 1; return Number(b._count?.memories || 0) - Number(a._count?.memories || 0); }).slice(0, 4));
const weekEventCount = computed(() => weekReminders.value.length); const weekMemoryCount = computed(() => focusPeople.value.reduce((sum, item) => sum + Number(item._count?.memories || 0), 0)); const weekRecordCount = computed(() => weekEventCount.value + weekMemoryCount.value); const insightCopy = computed(() => weekRecordCount.value ? `这周有 ${weekRecordCount.value} 条值得留意的记录，先从下一件重要的事开始。` : '从一个重要日子或一段回忆开始，让关系有迹可循。');

let loadGeneration = 0; const cancelPendingLoad = () => { loadGeneration += 1; }; onHide(cancelPendingLoad); onUnload(cancelPendingLoad);
const loadHome = async () => {
  const generation = ++loadGeneration;
  if (!store.isLogin) {
    relationships.value = [];
    upcomingReminders.value = [];
    todayReminders.value = [];
    loadError.value = false;
    loading.value = false;
    return;
  }
  loading.value = true;
  loadError.value = false;
  try {
    const [people, occurrences] = await Promise.all([relationshipApi.list(store.userId), eventApi.upcoming(90)]);
    if (generation !== loadGeneration) return;
    relationships.value = people || [];
    upcomingReminders.value = occurrences || [];
    todayReminders.value = (occurrences || []).filter((item) => eventDays(item) === 0);
    trackEvent('home_viewed', { relationshipCount: relationships.value.length, upcomingCount: upcomingReminders.value.length });
  } catch (error) {
    if (generation === loadGeneration) loadError.value = true;
  } finally {
    if (generation === loadGeneration) loading.value = false;
  }
};
onShow(loadHome);
const toDateKey = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; const personName = (item) => item.relationshipName || (item.sourceType === 'SPACE' ? '共同空间' : '重要的人'); const dayNumber = (value) => String(new Date(value).getDate()).padStart(2, '0'); const monthLabel = (value) => `${new Date(value).getMonth() + 1}月`; const shortDate = (value) => `${new Date(value).getMonth() + 1}.${String(new Date(value).getDate()).padStart(2, '0')}`;
const requireLogin = () => uni.showModal({ title: '需要登录', content: '登录后可保存关系、日期和回忆。', confirmText: '去登录', cancelText: '暂不登录', success: ({ confirm }) => { if (confirm) uni.navigateTo({ url: '/pages/login/login' }); } });
const goReminder = (item) => store.isLogin ? uni.navigateTo({ url: item.sourceType === 'SPACE' ? `/pages/space/detail?id=${item.sharedSpaceId}` : `/pages/event/detail?id=${item.eventId}&relationshipId=${item.relationshipId}` }) : requireLogin(); const openAI = (type, item) => store.isLogin ? uni.navigateTo({ url: `/pages/ai/${type}?relationshipId=${item.relationshipId || ''}` }) : requireLogin(); const goProfile = () => store.isLogin ? uni.reLaunch({ url: '/pages/profile/index' }) : requireLogin(); const goCalendar = () => store.isLogin ? uni.reLaunch({ url: '/pages/reminder/list' }) : requireLogin(); const goCalendarDay = (date) => store.isLogin ? uni.reLaunch({ url: `/pages/reminder/list?date=${date}` }) : requireLogin(); const goRelationships = () => store.isLogin ? uni.reLaunch({ url: '/pages/relationship/list' }) : requireLogin(); const goMemories = () => store.isLogin ? uni.reLaunch({ url: '/pages/memory/list' }) : requireLogin(); const goDetail = (id) => store.isLogin ? uni.navigateTo({ url: `/pages/relationship/detail?id=${id}` }) : requireLogin(); const goCreateRelationship = () => store.isLogin ? openContactCreationMenu() : requireLogin();
const chooseRelationship = (path) => { if (!relationships.value.length) return goCreateRelationship(); uni.showActionSheet({ itemList: relationships.value.map((item) => item.name), success: ({ tapIndex }) => uni.navigateTo({ url: `${path}?relationshipId=${relationships.value[tapIndex].id}` }) }); }; const addEvent = () => chooseRelationship('/pages/event/create'); const openCreateMenu = () => uni.showActionSheet({ itemList: ['添加联系人', '添加重要日子', '记录回忆'], success: ({ tapIndex }) => { if (tapIndex === 0) goCreateRelationship(); if (tapIndex === 1) addEvent(); if (tapIndex === 2) chooseRelationship('/pages/memory/create'); } });
const onAvatarError = () => { avatarLoadFailed.value = true; };
</script>

<style scoped>
