ht:1.55}.insight-stats{margin-top:18rpx;padding:14rpx 0;display:grid;grid-template-columns:repeat(3,1fr);text-align:center;border-top:1rpx solid #e4e6e1;border-bottom:1rpx solid #e4e6e1}.insight-stats view{display:flex;flex-direction:column}.insight-stats view+view{border-left:1rpx solid #e4e6e1}.insight-stats strong{font-size:38rpx;font-weight:500}.insight-stats text{margin-top:3rpx;color:#8b918d;font-size:25rpx}.quiet-button{width:100%;height:78rpx;margin-top:18rpx;padding:0;border:0;background:transparent;color:#315c4d;line-height:78rpx;font-size:28rpx;text-align:left}.week-section,.people-section{margin-top:32rpx}.week-strip{height:136rpx;margin-top:12rpx;padding:8rpx 4rpx;display:grid;grid-template-columns:repeat(7,1fr);border-top:1rpx solid #e0e3de;border-bottom:1rpx solid #e0e3de}.week-strip>view{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#8b918d}.week-strip>view text:first-child{font-size:25rpx}.week-strip>view text:nth-child(2){margin-top:7rpx;font-size:32rpx}.week-strip>view.today text:nth-child(2){width:58rpx;height:58rpx;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#315c4d;color:#fff}.day-dot{position:absolute;bottom:2rpx;width:6rpx;height:6rpx;border-radius:50%}.week-strip>view.busy .day-dot{background:#c76755}.agenda-list,.people-list{margin-top:8rpx}.agenda-row,.person-row{min-height:132rpx;border-bottom:1rpx solid #e4e6e1}.agenda-avatar,.person-avatar{width:78rpx;height:78rpx;margin-right:15rpx;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#e1e9e4;color:#3d6658;font-size:29rpx;font-weight:700;flex:none}.agenda-row>view:nth-child(2),.person-copy{flex:1;min-width:0;display:flex;flex-direction:column}.agenda-row>view:nth-child(2) text:first-child,.person-copy text:first-child{font-size:31rpx;font-weight:650}.agenda-row>view:nth-child(2) text:last-child,.person-copy text:last-child{margin-top:5rpx;color:#8c938e;font-size:27rpx}.agenda-when,.person-next{width:112rpx;display:flex;flex-direction:column;align-items:flex-end}.agenda-when text:first-child,.person-next text:first-child{color:#a65749;font-size:27rpx;font-weight:650}.agenda-when text:last-child,.person-next text:last-child{margin-top:4rpx;color:#9aa09c;font-size:25rpx}.quiet-empty{padding:38rpx 0;border-bottom:1rpx solid #e1e4df;color:#8b918d;font-size:28rpx;text-align:center}.tone-1{background:#e8dfca;color:#745f33}.tone-2{background:#dfe5ec;color:#526576}.tone-3{background:#eadde5;color:#765264}.row-arrow{color:#9ca29e;font-size:34rpx}.add-person-row{min-height:132rpx;border-top:1rpx solid #e1e4df;border-bottom:1rpx solid #e1e4df}.add-person-row>text:first-child{width:78rpx;height:78rpx;margin-right:15rpx;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#e4ece7;color:#315c4d;font-size:34rpx}.add-person-row>view{flex:1;display:flex;flex-direction:column}.add-person-row>view text:first-child{font-size:31rpx;font-weight:650}.add-person-row>view text:last-child{margin-top:5rpx;color:#8b918d;font-size:27rpx}.add-person-row>text:last-child,.shared-row>text{color:#9ca29e;font-size:34rpx}.shared-row{min-height:116rpx;margin-top:26rpx;padding:12rpx 0;border-top:1rpx solid #e0e3de}.shared-row>view:first-child{width:62rpx;height:62rpx;margin-right:15rpx;border-radius:9rpx;display:flex;align-items:center;justify-content:center;background:#f1e6d2;color:#80662f;font-size:26rpx;font-weight:700}.shared-row>view:nth-child(2){flex:1;display:flex;flex-direction:column}.shared-row>view:nth-child(2) text:first-child{font-size:31rpx;font-weight:650}.shared-row>view:nth-child(2) text:last-child{margin-top:4rpx;color:#8b918d;font-size:27rpx}
</style>
